<?php
session_start();require_once __DIR__.'/auth.php';ff_guard(); if(!isset($_SESSION['admin_id'])){header('Location: login.php');exit;}
require_once __DIR__.'/../fastfood/database.php'; require_once __DIR__.'/../fastfood/lang.php';
if($_SERVER['REQUEST_METHOD']==='POST'){ $type=$_POST['type']??'';$amount=(float)($_POST['amount']??0);$desc=trim($_POST['description']??'');if(in_array($type,['kirim','chiqim'],true)&&$amount>0&&$desc!==''){$pdo->prepare('INSERT INTO transactions(type,amount,description) VALUES(?,?,?)')->execute([$type,$amount,$desc]);} header('Location: transactions.php');exit; }
if(isset($_GET['delete'])){$pdo->prepare('DELETE FROM transactions WHERE id=?')->execute([(int)$_GET['delete']]);header('Location: transactions.php');exit;}
$from=$_GET['from']??date('Y-m-01');$to=$_GET['to']??date('Y-m-d');
$st=$pdo->prepare("SELECT COALESCE(SUM(CASE WHEN type='kirim' THEN amount ELSE 0 END),0) i, COALESCE(SUM(CASE WHEN type='chiqim' THEN amount ELSE 0 END),0) o FROM transactions WHERE DATE(created_at) BETWEEN ? AND ?");$st->execute([$from,$to]);$sum=$st->fetch();$in=(float)$sum['i'];$out=(float)$sum['o'];$rowsSt=$pdo->prepare('SELECT * FROM transactions WHERE DATE(created_at) BETWEEN ? AND ? ORDER BY created_at DESC');$rowsSt->execute([$from,$to]);$rows=$rowsSt->fetchAll();
$chart=[];$max=1;for($i=6;$i>=0;$i--){$d=date('Y-m-d',strtotime("-$i days"));$s=$pdo->prepare("SELECT COALESCE(SUM(CASE WHEN type='kirim' THEN amount ELSE 0 END),0) i, COALESCE(SUM(CASE WHEN type='chiqim' THEN amount ELSE 0 END),0) o FROM transactions WHERE DATE(created_at)=?");$s->execute([$d]);$r=$s->fetch();$r['label']=date('d M',strtotime($d));$chart[]=$r;$max=max($max,(float)$r['i'],(float)$r['o']);}
$lang=ff_current_lang();
?>
<!doctype html><html lang="<?=$lang?>"><head><meta charset="utf-8"><link rel="icon" type="image/svg+xml" href="../img/favicon.svg"><meta name="viewport" content="width=device-width,initial-scale=1"><title>FastFood — Moliya</title><link rel="stylesheet" href="../css/style.css"><link rel="stylesheet" href="../css/theme-elegant.css?v=2"><script src="../js/theme.js"></script><script src="../js/admin-i18n.js" defer></script><script src="../js/parallax.js?v=1" defer></script>
</head><body><?php include __DIR__.'/sidebar.php'; ?><main class="admin-content"><div class="page-topline"><div><div class="eyebrow" data-i18n="MOLIYA">MOLIYA</div><h1 data-i18n="Kirim / Chiqim">Kirim / Chiqim</h1><p class="admin-muted" data-i18n="Savdo va xarajatlarni nazorat qiling.">Savdo va xarajatlarni nazorat qiling.</p></div><form class="date-filter" method="get"><input type="date" name="from" value="<?=$from?>"><span>→</span><input type="date" name="to" value="<?=$to?>"><button class="btn btn-secondary" data-i18n="Filtr">Filtr</button></form></div>
<section class="metric-strip"><div><span data-i18n="Kirim">Kirim</span><strong><?=number_format($in,0,'',' ')?> <small>so‘m</small></strong></div><div><span data-i18n="Chiqim">Chiqim</span><strong><?=number_format($out,0,'',' ')?> <small>so‘m</small></strong></div><div><span data-i18n="Balans">Balans</span><strong><?=number_format($in-$out,0,'',' ')?> <small>so‘m</small></strong></div></section>
<section class="dashboard-grid-pro"><div class="admin-panel chart-panel"><div class="panel-heading"><div><div class="panel-kicker" data-i18n="7 KUN">7 KUN</div><h2 data-i18n="Kirim va chiqim">Kirim va chiqim</h2></div></div><div class="dual-chart"><?php foreach($chart as $d): ?><div class="dual-col"><div class="dual-bars"><i class="in-bar" style="height:<?=max(3,round((float)$d['i']/$max*100))?>%" title="<?=htmlspecialchars($d['i'])?>"></i><i class="out-bar" style="height:<?=max(3,round((float)$d['o']/$max*100))?>%" title="<?=htmlspecialchars($d['o'])?>"></i></div><small><?=$d['label']?></small></div><?php endforeach; ?></div><div class="chart-legend"><span><i class="dot in"></i><b data-i18n="Kirim">Kirim</b></span><span><i class="dot out"></i><b data-i18n="Chiqim">Chiqim</b></span></div></div>
<div class="admin-panel transaction-form-pro"><div class="panel-kicker" data-i18n="YANGI YOZUV">YANGI YOZUV</div><h2 data-i18n="Moliya yozuvi">Moliya yozuvi</h2><form method="post" class="stack-form"><label data-i18n="Turi">Turi<select name="type"><option value="kirim" data-i18n="Kirim">Kirim</option><option value="chiqim" data-i18n="Chiqim">Chiqim</option></select></label><label data-i18n="Summa">Summa<input type="number" name="amount" min="1" step="0.01" required></label><label data-i18n="Izoh">Izoh<input name="description" required placeholder="Masalan: mahsulot xaridi" data-i18n-placeholder="Masalan: mahsulot xaridi"></label><button class="btn" data-i18n="Saqlash">Saqlash</button></form></div></section>
<div class="admin-panel table-panel-pro"><div class="panel-heading"><div><div class="panel-kicker" data-i18n="JURNAL">JURNAL</div><h2 data-i18n="Moliya tarixi">Moliya tarixi</h2></div><span class="soft-count"><?=count($rows)?></span></div><div class="table-scroll"><table><thead><tr><th data-i18n="Sana">Sana</th><th data-i18n="Turi">Turi</th><th data-i18n="Izoh">Izoh</th><th data-i18n="Summa">Summa</th><th></th></tr></thead><tbody><?php foreach($rows as $r): ?><tr><td><?=htmlspecialchars($r['created_at'])?></td><td><span class="status-pill <?=$r['type']==='kirim'?'success':'danger'?>"><?=$r['type']==='kirim'?'Kirim':'Chiqim'?></span></td><td><?=htmlspecialchars($r['description'])?></td><td><strong><?=number_format($r['amount'],0,'',' ')?> so‘m</strong></td><td><a class="icon-btn danger" href="transactions.php?delete=<?=$r['id']?>" onclick="return confirm('O‘chirilsinmi?')">×</a></td></tr><?php endforeach; if(!$rows): ?><tr><td colspan="5" class="empty-table" data-i18n="Tanlangan davrda yozuv yo‘q.">Tanlangan davrda yozuv yo‘q.</td></tr><?php endif; ?></tbody></table></div></div>
</main><script src="../js/lang-switch.js"></script></body></html>
